export const envelope = [56, 32, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Array(W * H * D);

  function setBlock(x, y, z, block) {
    x = Math.floor(x);
    y = Math.floor(y);
    z = Math.floor(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x * H * D + y * D + z] = block;
    }
  }

  function getBlock(x, y, z) {
    x = Math.floor(x);
    y = Math.floor(y);
    z = Math.floor(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x * H * D + y * D + z] || null;
    }
    return null;
  }

  const cx = 27.5;
  const cz = 27.5;

  // -------------------------------------------------------------
  // 1. GROUND IMPACT CRATER & SCORCHED EARTH
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const rg = Math.hypot(x - cx, z - cz);
      if (rg > 15) continue;

      const h = api.heightAt(x, z);
      const baseY = Math.min(0, Math.floor(h)) - 1;
      const surfY = Math.max(0, Math.floor(h));

      // Fill solid foundation to terrain
      for (let y = baseY; y <= surfY; y++) {
        if (rg <= 3.5) {
          setBlock(x, y, z, (x + z + y) % 3 === 0 ? "minecraft:crying_obsidian" : "minecraft:obsidian");
        } else if (rg <= 7.5) {
          setBlock(x, y, z, (x + z) % 2 === 0 ? "minecraft:polished_blackstone" : "minecraft:sculk");
        } else {
          setBlock(x, y, z, "minecraft:blackstone");
        }
      }

      // Surface detailing: glyphs, crying obsidian veins & rupture spikes
      const angle = Math.atan2(z - cz, x - cx);
      const isRunicRing = Math.abs(rg - 5.5) < 0.7 || Math.abs(rg - 8.5) < 0.6;
      const isRunicSpoke = Math.abs(Math.sin(angle * 4)) < 0.12;

      if (rg <= 3.0) {
        setBlock(x, surfY, z, (x + z) % 2 === 0 ? "minecraft:crying_obsidian" : "minecraft:magma_block");
      } else if (isRunicRing || isRunicSpoke) {
        setBlock(x, surfY, z, "minecraft:crying_obsidian");
      } else if (rg <= 9.0 && (x * 3 + z * 5) % 7 === 0) {
        setBlock(x, surfY, z, "minecraft:sculk_sensor");
      }

      // Erupted jagged chitin spikes around crater rim
      if (rg >= 5.0 && rg <= 7.5 && Math.sin(angle * 6) > 0.65) {
        const spikeHeight = 1 + Math.floor(Math.abs(Math.sin(angle * 3)) * 2.5);
        for (let sy = 1; sy <= spikeHeight; sy++) {
          setBlock(x, surfY + sy, z, sy === spikeHeight ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone_bricks");
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. CENTRAL SUPERWEAPON BEAM & ENERGY VORTEX (Y: 0 to 14)
  // -------------------------------------------------------------
  for (let y = 0; y <= 14; y++) {
    for (let x = 22; x <= 33; x++) {
      for (let z = 22; z <= 33; z++) {
        const rb = Math.hypot(x - cx, z - cz);
        if (rb > 4.5) continue;

        if (rb <= 1.2) {
          // Central high-intensity energy core
          if (y === 0) {
            setBlock(x, y, z, "minecraft:beacon");
          } else if (y % 2 === 0) {
            setBlock(x, y, z, "minecraft:sea_lantern");
          } else {
            setBlock(x, y, z, "minecraft:cyan_stained_glass");
          }
        } else if (rb <= 2.5) {
          // Helical swirling plasma sheath
          const angle = Math.atan2(z - cz, x - cx);
          const swirl = Math.sin(angle * 3 + y * 0.7);
          if (swirl > 0.35) {
            setBlock(x, y, z, "minecraft:cyan_stained_glass");
          } else if (swirl > -0.35) {
            setBlock(x, y, z, "minecraft:light_blue_stained_glass");
          } else {
            setBlock(x, y, z, "minecraft:crying_obsidian");
          }
        } else if (rb <= 3.8) {
          // Energy containment rings at y=3, y=7, y=11
          if (y === 3 || y === 7 || y === 11) {
            if (Math.abs(rb - 3.2) < 0.6) {
              setBlock(x, y, z, "minecraft:polished_blackstone_brick_slab[type=bottom]");
            }
            if (Math.abs(rb - 2.8) < 0.4 && (x + z) % 2 === 0) {
              setBlock(x, y, z, "minecraft:sea_lantern");
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 3. BIOMECHANICAL SIPHON TALONS / ANCHOR LEGS (4 DIAGONALS)
  // -------------------------------------------------------------
  for (let k = 0; k < 4; k++) {
    const legAngle = Math.PI / 4 + k * (Math.PI / 2);
    const cosA = Math.cos(legAngle);
    const sinA = Math.sin(legAngle);

    // Foot anchor firmly in terrain
    const footX = Math.round(cx + 14 * cosA);
    const footZ = Math.round(cz + 14 * sinA);
    const footH = api.heightAt(footX, footZ);
    const footBaseY = Math.min(0, Math.floor(footH)) - 2;
    const footSurfY = Math.max(0, Math.floor(footH));

    for (let fy = footBaseY; fy <= footSurfY; fy++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dz = -1; dz <= 1; dz++) {
          setBlock(footX + dx, fy, footZ + dz, "minecraft:polished_blackstone_bricks");
        }
      }
    }

    // Arched claw spline from Foot (r=14, y=0) -> Knee (r=20, y=16) -> Hip (r=16, y=13)
    const steps = 35;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const invT = 1 - t;
      const px = invT * invT * (cx + 14 * cosA) + 2 * invT * t * (cx + 20 * cosA) + t * t * (cx + 16 * cosA);
      const py = invT * invT * 0 + 2 * invT * t * 16.5 + t * t * 13.0;
      const pz = invT * invT * (cz + 14 * sinA) + 2 * invT * t * (cz + 20 * sinA) + t * t * (cz + 16 * sinA);

      const legRadius = 1.0 + 0.6 * Math.sin(t * Math.PI);

      for (let rx = -2; rx <= 2; rx++) {
        for (let ry = -2; ry <= 2; ry++) {
          for (let rz = -2; rz <= 2; rz++) {
            if (rx * rx + ry * ry + rz * rz <= legRadius * legRadius) {
              const bx = Math.round(px + rx);
              const by = Math.round(py + ry);
              const bz = Math.round(pz + rz);

              let block = "minecraft:polished_blackstone_bricks";
              if ((rx + ry + rz) % 2 === 0) block = "minecraft:crying_obsidian";
              if (Math.abs(t - 0.5) < 0.08 && ry >= 0) block = "minecraft:sea_lantern"; // Glowing knee node

              setBlock(bx, by, bz, block);
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 4. MAIN HULL CARAPACE & BIO-MECHANICAL AIRFRAME (Y: 10 to 30)
  // -------------------------------------------------------------
  for (let x = 1; x < W - 1; x++) {
    for (let z = 1; z < D - 1; z++) {
      for (let y = 10; y <= 30; y++) {
        const dx = x - cx;
        const dz = z - cz;

        let inSolid = false;
        let isEnergySeam = false;
        let isArmorPlate = false;

        // A. Central Saucer / Fuselage
        const bodyDist = Math.hypot(dx * 1.05, dz * (dz < 0 ? 0.95 : 0.85));
        const maxBodyDist = 19.0;

        if (bodyDist <= maxBodyDist) {
          const normR = bodyDist / maxBodyDist;
          const yBot = 13.0 - 3.5 * Math.pow(Math.max(0, 1.0 - normR * normR), 0.7);
          const yTop = 16.5 + 8.5 * Math.pow(Math.max(0, 1.0 - Math.pow(normR, 1.6)), 0.65);

          if (y >= yBot && y <= yTop) {
            inSolid = true;
          }
        }

        // B. Forward Mandibles (Prow Scythes facing North -Z)
        if (z >= 3 && z <= 24) {
          const mandXLeft = 20.5 - 5.5 * Math.sin(((24 - z) / 21) * Math.PI * 0.5);
          const mandXRight = 55 - mandXLeft;
          const mandW = 0.8 + 3.2 * ((z - 2) / 22);
          const mandYMid = 14.0 + 3.0 * (z / 24);
          const mandTh = 0.8 + 2.2 * ((z - 2) / 22);

          // Left Mandible
          if (Math.abs(x - mandXLeft) <= mandW && Math.abs(y - mandYMid) <= mandTh) {
            inSolid = true;
            if (x > mandXLeft - 0.4 && x < mandXLeft + 1.8 && Math.abs(y - mandYMid) < 0.8) {
              isEnergySeam = true; // Inner plasma blade
            }
          }

          // Right Mandible
          if (Math.abs(x - mandXRight) <= mandW && Math.abs(y - mandYMid) <= mandTh) {
            inSolid = true;
            if (x < mandXRight + 0.4 && x > mandXRight - 1.8 && Math.abs(y - mandYMid) < 0.8) {
              isEnergySeam = true; // Inner plasma blade
            }
          }
        }

        // C. Swept Lateral Wings / Outriggers
        const wingXt = Math.abs(dx) / (cx - 2);
        if (wingXt >= 0.35 && wingXt <= 1.0) {
          const wingZMid = 26.0 + wingXt * 9.0;
          const wingChord = 12.0 * (1.0 - wingXt * 0.65);
          const wingYMid = 14.5 + Math.pow(wingXt, 2.2) * 4.5;
          const wingTh = 0.9 + 2.4 * (1.0 - wingXt);

          if (Math.abs(z - wingZMid) <= wingChord * 0.5 && Math.abs(y - wingYMid) <= wingTh) {
            inSolid = true;
            // Wing leading edge glowing conduit
            if (Math.abs(z - (wingZMid - wingChord * 0.45)) < 1.0) {
              isEnergySeam = true;
            }
          }
        }

        // D. Rear Propulsion Bio-Nacelles (Thrusters facing South +Z)
        if (z >= 30 && z <= 51) {
          const nacMaxR = z > 47 ? 4.2 : 3.6;
          const nacRLeft = Math.hypot(x - 17.5, y - 16.0);
          const nacRRight = Math.hypot(x - 37.5, y - 16.0);

          if (nacRLeft <= nacMaxR || nacRRight <= nacMaxR) {
            inSolid = true;
            if (z >= 48) {
              if (nacRLeft <= 2.2 || nacRRight <= 2.2) {
                isEnergySeam = true;
              }
            }
          }
        }

        // E. Dorsal Spine & Bio-Carapace Crest
        if (z >= 8 && z <= 44 && Math.abs(dx) <= 1.6) {
          const spineZNorm = (z - 8) / 36;
          const spinePeakY = 23.0 + 6.0 * Math.sin(spineZNorm * Math.PI);
          const finRidge = Math.sin(z * 1.5) > 0.4 ? 1.5 : 0.0;
          const spineYTop = spinePeakY + finRidge;

          if (y >= 16 && y <= spineYTop) {
            inSolid = true;
            if (Math.abs(y - spineYTop) < 1.0) {
              isArmorPlate = true;
            }
          }
        }

        // F. Rear Organic Rudder
        if (z >= 40 && z <= 48 && Math.abs(dx) <= 1.2 && y >= 16 && y <= (22 + (48 - z) * 0.7)) {
          inSolid = true;
        }

        // Apply Block Palette
        if (inSolid) {
          if (isEnergySeam) {
            setBlock(x, y, z, (x + y + z) % 2 === 0 ? "minecraft:sea_lantern" : "minecraft:cyan_stained_glass");
          } else if (isArmorPlate) {
            setBlock(x, y, z, (z % 3 === 0) ? "minecraft:sculk" : "minecraft:crying_obsidian");
          } else {
            const rib = (Math.floor(x + z) % 4 === 0);
            if (y >= 20) {
              if (rib) {
                setBlock(x, y, z, "minecraft:crying_obsidian");
              } else if (Math.abs(dx) <= 1.5 && z % 3 === 0) {
                setBlock(x, y, z, "minecraft:sculk");
              } else if ((x + y + z) % 7 === 0) {
                setBlock(x, y, z, "minecraft:deepslate_tiles");
              } else {
                setBlock(x, y, z, "minecraft:polished_blackstone_bricks");
              }
            } else if (y <= 13) {
              setBlock(x, y, z, rib ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone");
            } else {
              setBlock(x, y, z, rib ? "minecraft:crying_obsidian" : "minecraft:polished_blackstone_bricks");
            }
          }
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 5. HOLLOW OUT INTERIORS (ROOMS FOR COMPILER FIT-OUT)
  // -------------------------------------------------------------

  // Upper Deck: Mothership Bridge / Hive Command
  for (let x = 23; x <= 32; x++) {
    for (let z = 17; z <= 27; z++) {
      for (let y = 19; y <= 23; y++) {
        setBlock(x, y, z, null);
      }
    }
  }

  // Bridge Floor (y = 18)
  for (let x = 22; x <= 33; x++) {
    for (let z = 16; z <= 28; z++) {
      let floorBlock = "minecraft:polished_blackstone_bricks";
      if (x === 27 || x === 28 || z === 22) floorBlock = "minecraft:sea_lantern";
      if (x === 22 || x === 33 || z === 16 || z === 28) floorBlock = "minecraft:crying_obsidian";
      setBlock(x, 18, z, floorBlock);
    }
  }

  // Bridge Ceiling Reinforcement (y = 24)
  for (let x = 22; x <= 33; x++) {
    for (let z = 16; z <= 28; z++) {
      if (getBlock(x, 24, z) === null) {
        setBlock(x, 24, z, "minecraft:polished_blackstone_bricks");
      }
    }
  }

  // Panoramic Front Viewport (z = 16, facing North)
  for (let x = 24; x <= 31; x++) {
    for (let y = 19; y <= 22; y++) {
      setBlock(x, y, 16, "minecraft:cyan_stained_glass");
    }
  }

  // Lower Deck: Reactor / Gravity Core Vault
  for (let x = 25; x <= 30; x++) {
    for (let z = 25; z <= 30; z++) {
      for (let y = 14; y <= 17; y++) {
        setBlock(x, y, z, null);
      }
    }
  }

  // Reactor Floor with Observation Aperture (y = 13)
  for (let x = 24; x <= 31; x++) {
    for (let z = 24; z <= 31; z++) {
      if (x >= 26 && x <= 29 && z >= 26 && z <= 29) {
        setBlock(x, 13, z, "minecraft:cyan_stained_glass");
      } else {
        setBlock(x, 13, z, "minecraft:crying_obsidian");
      }
    }
  }

  // Vertical Gravity Lift Shaft (Connecting Lower Vault to Upper Bridge)
  for (let y = 13; y <= 19; y++) {
    setBlock(26, y, 26, "minecraft:sea_lantern");
    setBlock(29, y, 26, "minecraft:sea_lantern");
    setBlock(26, y, 27, "minecraft:sea_lantern");
    setBlock(29, y, 27, "minecraft:sea_lantern");
    setBlock(27, y, 26, null);
    setBlock(28, y, 26, null);
    setBlock(27, y, 27, null);
    setBlock(28, y, 27, null);
  }

  // -------------------------------------------------------------
  // 6. EXTERIOR DETAIL ACCENTS (EXHAUSTS, SPINES & ANTENNAS)
  // -------------------------------------------------------------

  // Rear Plasma Thruster Particle Exhausts
  setBlock(17, 16, 52, "minecraft:end_rod[facing=south]");
  setBlock(18, 16, 52, "minecraft:end_rod[facing=south]");
  setBlock(17, 16, 53, "minecraft:cyan_stained_glass");
  setBlock(18, 16, 53, "minecraft:cyan_stained_glass");
  setBlock(17, 16, 54, "minecraft:end_rod[facing=south]");

  setBlock(37, 16, 52, "minecraft:end_rod[facing=south]");
  setBlock(38, 16, 52, "minecraft:end_rod[facing=south]");
  setBlock(37, 16, 53, "minecraft:cyan_stained_glass");
  setBlock(38, 16, 53, "minecraft:cyan_stained_glass");
  setBlock(38, 16, 54, "minecraft:end_rod[facing=south]");

  // Mandible Tip Fangs
  setBlock(15, 14, 3, "minecraft:end_rod[facing=north]");
  setBlock(40, 14, 3, "minecraft:end_rod[facing=north]");

  // Wingtip Sensor Spines
  setBlock(2, 19, 32, "minecraft:lightning_rod[facing=up]");
  setBlock(2, 20, 32, "minecraft:end_rod[facing=up]");
  setBlock(53, 19, 32, "minecraft:lightning_rod[facing=up]");
  setBlock(53, 20, 32, "minecraft:end_rod[facing=up]");

  // Dorsal Carapace Spines
  setBlock(27, 29, 18, "minecraft:lightning_rod[facing=up]");
  setBlock(28, 29, 18, "minecraft:lightning_rod[facing=up]");
  setBlock(27, 30, 24, "minecraft:end_rod[facing=up]");
  setBlock(28, 30, 24, "minecraft:end_rod[facing=up]");
  setBlock(27, 29, 30, "minecraft:lightning_rod[facing=up]");
  setBlock(28, 29, 30, "minecraft:lightning_rod[facing=up]");

  // -------------------------------------------------------------
  // 7. EMIT TO WORLD API
  // -------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x * H * D + y * D + z];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Alien Mothership",
    seatY: 0,
    anchors: {
      front: [28, 20, 0],
      core: [27, 14, 27],
      beam_target: [28, 0, 28]
    },
    interiors: [
      { min: [23, 19, 17], max: [32, 23, 27], kind: "bridge" },
      { min: [25, 14, 25], max: [30, 17, 30], kind: "vault" }
    ]
  };
}

