export const envelope = [22, 12, 22];

export default function build(api) {
  const [W, H, D] = envelope;
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => Array(D).fill(null))
  );

  function setVoxel(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      grid[ix][iy][iz] = block;
    }
  }

  // 1. FURROWED EARTH & IMPACT TRENCH
  // The saucer skidded from South (+Z) towards North (-Z), gouging a furrow
  // and throwing up berms of churned soil, mud, and scorched terrain.
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = Math.abs(x - 10.5);
      const tz = (z - 2) / 18.0; // 0 at front impact, 1 at skid tail

      // Impact crater bowl at the nose (z ~ 3..8)
      const rBowl = Math.sqrt((x - 10.5) ** 2 + (z - 5.5) ** 2);
      let hRim = 0;
      if (rBowl >= 3.5 && rBowl <= 7.8) {
        hRim = Math.max(0, 3.4 - 0.7 * Math.abs(rBowl - 5.6) ** 1.8);
      }

      // Flanking skid berms along the furrow sides (z ~ 8..19, dx ~ 3.5..7.5)
      let hFlank = 0;
      if (z >= 7 && dx >= 3.0 && dx <= 7.5) {
        const lateralFactor = 1.0 - Math.abs(dx - 5.2) / 2.5;
        const forwardFactor = 1.0 - 0.55 * tz;
        hFlank = Math.max(0, 2.6 * lateralFactor * forwardFactor);
      }

      // Base terrain layer
      let topY = Math.max(hRim, hFlank);
      const inTrough = dx <= 3.2 && z >= 4 && z <= 17;
      if (inTrough) {
        topY = Math.min(topY, 0.4); // Ploughed depression where the hull rests
      } else {
        topY = Math.max(topY, 0.8);
      }

      const maxGroundY = Math.min(H - 1, Math.floor(topY));

      for (let y = 0; y <= maxGroundY; y++) {
        // Scorched core near high-energy nose impact
        if (rBowl <= 4.2 && y <= maxGroundY) {
          const scorchSeed = (x * 7 + z * 13 + y * 3) % 10;
          if (scorchSeed < 4) {
            setVoxel(x, y, z, "minecraft:magma_block");
          } else if (scorchSeed < 7) {
            setVoxel(x, y, z, "minecraft:crying_obsidian");
          } else {
            setVoxel(x, y, z, "minecraft:blackstone");
          }
        } else if (y === maxGroundY) {
          // Top layer of churned farm soil
          const soilSeed = (x * 11 + z * 17) % 10;
          if (soilSeed < 3) {
            setVoxel(x, y, z, "minecraft:coarse_dirt");
          } else if (soilSeed < 6) {
            setVoxel(x, y, z, "minecraft:rooted_dirt");
          } else if (soilSeed < 8) {
            setVoxel(x, y, z, "minecraft:mud");
          } else {
            setVoxel(x, y, z, "minecraft:podzol[snowy=false]");
          }
        } else {
          // Sub-surface dirt
          setVoxel(x, y, z, "minecraft:dirt");
        }
      }
    }
  }

  // 2. TILTED METALLIC SAUCER GEOMETRY
  // Disc parameters in local rotated coordinate space
  const cx = 10.5;
  const cy = 4.8;
  const cz = 11.0;
  const theta = -0.31; // Tilted down towards North (-Z) by ~18 degrees
  const cosT = Math.cos(theta);
  const sinT = Math.sin(theta);
  const R_DISC = 7.6;

  for (let x = 1; x < W - 1; x++) {
    for (let y = 1; y < H - 1; y++) {
      for (let z = 1; z < D - 1; z++) {
        const dx = x - cx;
        const dy = y - cy;
        const dz = z - cz;

        // Transform into saucer plane coordinates:
        // u: lateral axis
        // v: normal axis (disc thickness)
        // w: longitudinal crash axis
        const u = dx;
        const v = dy * cosT - dz * sinT;
        const w = dy * sinT + dz * cosT;
        const r = Math.sqrt(u * u + w * w);

        if (r > R_DISC) continue;

        // Thickness envelope calculation
        let vTop, vBot;
        if (r <= 2.2) {
          // Central power dome & ventral core
          const domeH = Math.sqrt(Math.max(0, 1.0 - (r / 2.2) ** 2));
          vTop = 1.0 + 2.2 * domeH;
          vBot = -0.9 - 0.7 * domeH;
        } else if (r <= 5.8) {
          // Mid metallic hull slope
          const t = (r - 2.2) / 3.6;
          vTop = 1.0 * (1 - t) + 0.45 * t;
          vBot = -0.9 * (1 - t) - 0.35 * t;
        } else {
          // Outer beveled rim
          const t = (r - 5.8) / (R_DISC - 5.8);
          vTop = 0.45 * (1 - t) + 0.08 * t;
          vBot = -0.35 * (1 - t) - 0.08 * t;
        }

        // Check if inside saucer volume
        if (v < vBot - 0.15 || v > vTop + 0.15) continue;

        // 3. DAMAGE / FRACTURE & PLASMA CONDUIT BREACH
        // Forward port side struck the ground hardest, cracking open hull panels
        const isImpactSide = w < -1.0 && u >= -5.2 && u <= 1.5;
        const fractureWave =
          Math.sin(1.9 * u + 1.3 * w) + 0.55 * Math.cos(2.4 * u - 1.6 * w);
        const isCrackFissure = isImpactSide && Math.abs(fractureWave) < 0.38 && r >= 2.0;
        const isScorchedRim =
          isImpactSide && Math.abs(fractureWave) >= 0.38 && Math.abs(fractureWave) < 0.72;

        if (isCrackFissure) {
          // Exposed glowing plasma core, conduit wiring, and ruptured framework
          if (v >= 0.3) {
            setVoxel(x, y, z, "minecraft:cyan_stained_glass");
          } else if (v >= -0.3) {
            setVoxel(x, y, z, "minecraft:sea_lantern");
          } else {
            setVoxel(x, y, z, "minecraft:crying_obsidian");
          }
          continue;
        }

        if (isScorchedRim) {
          // Torn ionized hull plating edges
          const rimSeed = (x * 3 + y * 7 + z * 11) % 4;
          if (rimSeed === 0) {
            setVoxel(x, y, z, "minecraft:crying_obsidian");
          } else if (rimSeed === 1) {
            setVoxel(x, y, z, "minecraft:smooth_basalt");
          } else {
            setVoxel(x, y, z, "minecraft:weathered_cut_copper");
          }
          continue;
        }

        // 4. INTACT SAUCER METALLIC HULL PLATING
        if (r <= 2.2) {
          // Central Cockpit / Energy Bubble
          if (v > 1.2) {
            if (r <= 1.3 && v <= 2.3) {
              setVoxel(x, y, z, "minecraft:sea_lantern"); // Glowing core
            } else {
              setVoxel(x, y, z, "minecraft:cyan_stained_glass"); // Translucent canopy
            }
          } else if (v >= -0.2) {
            // Dome collar ring
            setVoxel(x, y, z, "minecraft:chiseled_copper");
          } else {
            // Ventral antigrav projector node
            if (r <= 1.2) {
              setVoxel(x, y, z, "minecraft:sea_lantern");
            } else {
              setVoxel(x, y, z, "minecraft:crying_obsidian");
            }
          }
        } else if (r <= 5.8) {
          // Mid Hull: concentric alloy rings & radial emitter nodes
          const angle = Math.atan2(w, u) + Math.PI;
          const radialSeam = (angle % (Math.PI / 3)) < 0.18;

          if (v < -0.35) {
            // Underbelly propulsion track
            if (r >= 3.8 && r <= 4.6) {
              setVoxel(x, y, z, "minecraft:crying_obsidian");
            } else {
              setVoxel(x, y, z, "minecraft:smooth_basalt");
            }
          } else if (radialSeam) {
            // Radial conduit panel seams
            setVoxel(x, y, z, "minecraft:weathered_cut_copper");
          } else if (r >= 4.2 && r <= 4.9) {
            // Energy ring with periodic luminescent nodes
            const bulbNode = (angle % (Math.PI / 3)) < 0.45;
            if (bulbNode && v >= 0.2) {
              setVoxel(x, y, z, "minecraft:sea_lantern");
            } else {
              setVoxel(x, y, z, "minecraft:weathered_cut_copper");
            }
          } else if (r <= 3.4) {
            // Inner hull plate
            setVoxel(x, y, z, "minecraft:iron_block");
          } else {
            // Outer mid plate
            setVoxel(x, y, z, "minecraft:smooth_quartz");
          }
        } else {
          // Outer Perimeter Beveled Rim
          if (v >= 0.1) {
            setVoxel(x, y, z, "minecraft:iron_block");
          } else {
            setVoxel(x, y, z, "minecraft:smooth_basalt");
          }
        }
      }
    }
  }

  // 5. EXPOSED SPARKS, WIRING & CONDUITS AT THE BREACH
  // Jagged iron struts and conduits protruding from torn plating
  const conduitPoints = [
    [7, 3, 6, "minecraft:end_rod[facing=up]"],
    [8, 4, 7, "minecraft:iron_bars"],
    [6, 3, 8, "minecraft:iron_bars"],
    [9, 4, 6, "minecraft:end_rod[facing=north]"],
    [7, 4, 5, "minecraft:sea_lantern"],
  ];
  for (const [cxp, cyp, czp, block] of conduitPoints) {
    if (!grid[cxp][cyp][czp]) {
      setVoxel(cxp, cyp, czp, block);
    }
  }

  // 6. DISPLACED HULL SHARD (Ejected panel embedded in the east berm)
  setVoxel(16, 2, 7, "minecraft:weathered_cut_copper");
  setVoxel(16, 3, 7, "minecraft:iron_block");
  setVoxel(17, 2, 8, "minecraft:weathered_cut_copper");
  setVoxel(16, 4, 7, "minecraft:end_rod[facing=up]");

  // 7. CRUSHED FARM REMNANTS (Agrarian town elements caught in impact)
  // Smashed fence line along z = 16
  const fencePosts = [
    [3, 1, 16],
    [3, 2, 16],
    [4, 1, 16],
    [17, 1, 16],
    [17, 2, 16],
    [18, 1, 16],
  ];
  for (const [fx, fy, fz] of fencePosts) {
    setVoxel(fx, fy, fz, "minecraft:oak_fence");
  }

  // Crushed hay bales ploughed aside into the trench rim
  setVoxel(15, 1, 13, "minecraft:hay_block[axis=y]");
  setVoxel(15, 2, 13, "minecraft:hay_block[axis=z]");
  setVoxel(16, 1, 12, "minecraft:hay_block[axis=x]");
  setVoxel(5, 1, 12, "minecraft:hay_block[axis=x]");

  // 8. WRITE ALL DETERMINISTICALLY TO WORLD
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = grid[x][y][z];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Crashed Scout Saucer",
    seatY: 0,
    anchors: {
      front: [11, 1, 0], // Saucer crashed heading North (-Z)
      impact: [11, 1, 5],
    },
  };
}

