export const envelope = [10, 11, 10];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 2;
  const cx = 4.5;
  const cz = 4.5;

  // 3D voxel buffer for deterministic placement and connectivity
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => Array(D).fill(null))
  );

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  // PRNG seed variations per instance
  const rnd = () => api.random();
  const instIdx = api.instance.index;

  // Pod tilt: backward (+Z) with slight lateral drift, nose punch angled into the farm soil
  const tiltX = (rnd() - 0.5) * 0.28;
  const tiltZ = 0.18 + rnd() * 0.22;

  // Aesthetic variations
  const podVariant = instIdx % 3; // 0: Crying Obsidian heavy, 1: Polished Chitin, 2: Sculk Biomechanical
  const glowType = (instIdx + 1) % 3; // 0: Sea Lantern (cyan bio), 1: Ochre Froglight (amber core), 2: Shroomlight / Sculk
  const hatchMode = instIdx % 4; // 0: Blown forward on ground, 1: Canopy hinged up, 2: Split blast doors, 3: Melted breach

  const primaryArmor =
    podVariant === 0
      ? "minecraft:crying_obsidian"
      : podVariant === 1
      ? "minecraft:polished_blackstone_bricks"
      : "minecraft:polished_blackstone";

  const secondaryArmor =
    podVariant === 0
      ? "minecraft:polished_blackstone"
      : podVariant === 1
      ? "minecraft:chiseled_polished_blackstone"
      : "minecraft:crying_obsidian";

  const ribBlock =
    podVariant === 2
      ? "minecraft:sculk"
      : "minecraft:polished_blackstone_bricks";

  const bioGlow1 =
    glowType === 0
      ? "minecraft:sea_lantern"
      : glowType === 1
      ? "minecraft:ochre_froglight"
      : "minecraft:sculk_catalyst";

  const bioGlow2 =
    glowType === 0
      ? "minecraft:crying_obsidian"
      : glowType === 1
      ? "minecraft:magma_block"
      : "minecraft:shroomlight";

  // 1. IMPACT CRATER & SUB-SURFACE COMPACTION (y = 0 to 2)
  // Ensure solid base connection and high voxel count
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dist = Math.hypot(x - cx, z - cz);

      // Local terrain support down to ground
      const th = api.heightAt(x, z);
      const groundLevel = Math.max(0, seatY + th);

      // Subterranean solid impact bed (y = 0)
      if (dist <= 4.6) {
        put(
          x,
          0,
          z,
          rnd() < 0.6 ? "minecraft:basalt" : "minecraft:blackstone"
        );
      }

      // Layer 1: Churned scorched earth & deep crater base
      if (dist <= 4.4) {
        if (dist <= 2.2) {
          put(
            x,
            1,
            z,
            rnd() < 0.4
              ? "minecraft:magma_block"
              : rnd() < 0.7
              ? "minecraft:crying_obsidian"
              : "minecraft:blackstone"
          );
        } else {
          put(
            x,
            1,
            z,
            rnd() < 0.5
              ? "minecraft:basalt"
              : rnd() < 0.8
              ? "minecraft:coarse_dirt"
              : "minecraft:blackstone"
          );
        }
      }

      // Layer 2: Crater lip and scorched soil ring (seat level)
      if (dist >= 2.6 && dist <= 4.3) {
        const rimNoise = rnd();
        if (rimNoise < 0.75) {
          put(
            x,
            2,
            z,
            rimNoise < 0.35
              ? "minecraft:basalt"
              : rimNoise < 0.6
              ? "minecraft:coarse_dirt"
              : "minecraft:magma_block"
          );
        }
      }

      // Occasional raised impact debris crest at y = 3
      if (dist >= 3.3 && dist <= 4.1 && rnd() < 0.4) {
        put(
          x,
          3,
          z,
          rnd() < 0.5
            ? "minecraft:polished_blackstone_slab[type=bottom]"
            : "minecraft:blackstone"
        );
      }

      // Fill downwards under terrain if slope falls away
      for (let y = 0; y < groundLevel; y++) {
        if (dist <= 4.2 && !grid[x][y][z]) {
          put(x, y, z, "minecraft:blackstone");
        }
      }
    }
  }

  // 2. POD HULL & INTERNAL BIOMECHANICAL CORE (y = 1 to 10)
  // Hull radius profile from nose (y=1) to spire tip (y=10)
  const radiusProfile = [
    1.4, // y=0 (buried nose)
    1.9, // y=1
    2.4, // y=2
    2.7, // y=3 (widest pod belly)
    2.7, // y=4
    2.5, // y=5
    2.2, // y=6
    1.8, // y=7
    1.4, // y=8
    0.9, // y=9
    0.5, // y=10 (top apex)
  ];

  for (let y = 1; y < H; y++) {
    // Tilted center axis
    const px = cx + (y - 2) * tiltX;
    const pz = cz + (y - 2) * tiltZ;
    const maxR = radiusProfile[y];
    const innerR = Math.max(0.6, maxR - 0.95);

    for (let x = 0; x < W; x++) {
      for (let z = 0; z < D; z++) {
        const dist = Math.hypot(x - px, z - pz);
        if (dist > maxR) continue;

        const isNorthHatchZone =
          z < pz - 0.4 && Math.abs(x - px) <= 1.4 && y >= 2 && y <= 6;

        // Inside pod interior hollow
        if (dist < innerR && y >= 2 && y <= 7) {
          // Central glowing energy core pillar
          if (dist <= 0.85) {
            if (y === 2) put(x, y, z, bioGlow2);
            else if (y === 3) put(x, y, z, bioGlow1);
            else if (y === 4) put(x, y, z, "minecraft:crying_obsidian");
            else if (y === 5) put(x, y, z, bioGlow1);
            else if (y === 6) put(x, y, z, bioGlow2);
            else if (y === 7) put(x, y, z, "minecraft:crying_obsidian");
          } else if (!isNorthHatchZone) {
            // Internal conduit / cage struts
            if (y === 3 || y === 5) {
              if (rnd() < 0.3) put(x, y, z, "minecraft:iron_bars");
            }
          }
          // Do not fill interior with armor, keep open for glow visibility
          continue;
        }

        // Hull wall placement
        if (isNorthHatchZone) {
          // Open hatch opening facing North (-Z) - leave unobstructed to expose glowing core
          continue;
        }

        // Pod outer armor shell
        const armorPick = rnd();
        if (armorPick < 0.55) {
          put(x, y, z, primaryArmor);
        } else if (armorPick < 0.85) {
          put(x, y, z, secondaryArmor);
        } else {
          put(x, y, z, ribBlock);
        }
      }
    }
  }

  // 3. EXTERNAL STABILIZER FINS & SPIKES
  // 3 fins: East (~0 rad), West (~PI rad), South dorsal fin (~PI/2 rad)
  const finAngles = [-0.15, 3.25, 1.57];
  const hasDamagedFin = rnd() < 0.4;
  const brokenFinIdx = Math.floor(rnd() * 3);

  for (let f = 0; f < finAngles.length; f++) {
    if (hasDamagedFin && f === brokenFinIdx) continue; // broken off in crash
    const angle = finAngles[f];
    const cosA = Math.cos(angle);
    const sinA = Math.sin(angle);

    for (let y = 3; y <= 8; y++) {
      const px = cx + (y - 2) * tiltX;
      const pz = cz + (y - 2) * tiltZ;
      const hullR = radiusProfile[y];

      // Protrude fin outwards by 1 to 2 blocks
      const maxExt = y >= 4 && y <= 6 ? 2 : 1;
      for (let step = 1; step <= maxExt; step++) {
        const fx = Math.round(px + (hullR + step * 0.75) * cosA);
        const fz = Math.round(pz + (hullR + step * 0.75) * sinA);

        if (step === maxExt && y >= 6) {
          put(fx, y, fz, "minecraft:polished_blackstone_wall");
        } else {
          put(
            fx,
            y,
            fz,
            rnd() < 0.5
              ? "minecraft:crying_obsidian"
              : "minecraft:polished_blackstone"
          );
        }
      }
    }
  }

  // 4. OPEN HATCH DOOR / BLAST PLATES (North Side Facing -Z)
  const hatchY = 2;
  const frontPz = cz + (hatchY - 2) * tiltZ - radiusProfile[hatchY];

  if (hatchMode === 0) {
    // Blown-off armor hatch lying shattered in the North crater soil
    const doorZ = Math.max(0, Math.round(frontPz - 1.4));
    const doorX = Math.round(cx);
    put(doorX - 1, 2, doorZ, "minecraft:polished_blackstone_slab[type=bottom]");
    put(doorX, 2, doorZ, "minecraft:crying_obsidian");
    put(doorX + 1, 2, doorZ, "minecraft:polished_blackstone_slab[type=bottom]");
    put(doorX, 3, doorZ, "minecraft:polished_blackstone_wall");
    put(doorX, 2, doorZ + 1, "minecraft:magma_block");
  } else if (hatchMode === 1) {
    // Canopy hatch folded open upwards above entry
    const doorX = Math.round(cx);
    put(doorX - 1, 6, Math.round(frontPz - 0.5), "minecraft:polished_blackstone_slab[type=top]");
    put(doorX, 7, Math.round(frontPz - 0.8), "minecraft:crying_obsidian");
    put(doorX + 1, 6, Math.round(frontPz - 0.5), "minecraft:polished_blackstone_slab[type=top]");
    put(doorX, 6, Math.round(frontPz - 0.5), bioGlow1);
  } else if (hatchMode === 2) {
    // Twin blast doors swung open to left and right
    const doorX = Math.round(cx);
    const doorZ = Math.round(frontPz);
    put(doorX - 2, 2, doorZ, "minecraft:polished_blackstone");
    put(doorX - 2, 3, doorZ, "minecraft:polished_blackstone_wall");
    put(doorX - 2, 4, doorZ, "minecraft:crying_obsidian");
    put(doorX + 2, 2, doorZ, "minecraft:polished_blackstone");
    put(doorX + 2, 3, doorZ, "minecraft:polished_blackstone_wall");
    put(doorX + 2, 4, doorZ, "minecraft:crying_obsidian");
  } else {
    // Melted breaches with bio-matter slag
    const doorX = Math.round(cx);
    const doorZ = Math.round(frontPz);
    put(doorX - 1, 2, doorZ, "minecraft:magma_block");
    put(doorX + 1, 2, doorZ, "minecraft:sculk");
    put(doorX, 2, doorZ, "minecraft:crying_obsidian");
    put(doorX, 3, doorZ - 1, "minecraft:iron_bars");
  }

  // 5. APEX PLASMA VENT & TOP SPIRE (y = 9 to 10)
  const topX = Math.round(cx + (10 - 2) * tiltX);
  const topZ = Math.round(cz + (10 - 2) * tiltZ);
  put(topX, 9, topZ, "minecraft:crying_obsidian");
  put(topX, 10, topZ, "minecraft:end_rod[facing=up]");

  // Heat vent pipes on upper hull
  if (rnd() < 0.7) {
    put(topX + 1, 8, topZ, "minecraft:polished_blackstone_wall");
  }
  if (rnd() < 0.7) {
    put(topX - 1, 8, topZ, "minecraft:polished_blackstone_wall");
  }

  // 6. SCATTERED IMPACT CRUST & BIO-TENDRILS (ground level detail)
  const tendrilCount = 3 + Math.floor(rnd() * 3);
  for (let t = 0; t < tendrilCount; t++) {
    const tAngle = rnd() * Math.PI * 2;
    const tDist = 2.8 + rnd() * 1.5;
    const tx = Math.round(cx + Math.cos(tAngle) * tDist);
    const tz = Math.round(cz + Math.sin(tAngle) * tDist);
    if (tx >= 0 && tx < W && tz >= 0 && tz < D) {
      if (grid[tx][2][tz] === null && grid[tx][1][tz] !== null) {
        put(
          tx,
          2,
          tz,
          podVariant === 2
            ? "minecraft:sculk"
            : rnd() < 0.5
            ? "minecraft:crying_obsidian"
            : "minecraft:magma_block"
        );
      }
    }
  }

  // 7. ENSURE SOLID CONNECTIVITY & EMIT BLOCKS
  let solidCount = 0;
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block) {
          api.set(x, y, z, block);
          solidCount++;
        }
      }
    }
  }

  // Publish anchors for world alignment and invasion pathing
  const frontZ = 0;
  const frontX = Math.round(cx);

  return {
    name: `Alien Assault Pod #${instIdx + 1}`,
    seatY: seatY,
    anchors: {
      front: [frontX, seatY, frontZ],
      door: [frontX, seatY + 1, Math.max(1, Math.round(frontPz))],
      core: [
        Math.round(cx + 2 * tiltX),
        seatY + 2,
        Math.round(cz + 2 * tiltZ),
      ],
    },
  };
}
